import{_ as e,H as p,f as r,i}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"終章","description":"","frontmatter":{"title":"終章","outline":"deep"},"headers":[],"relativePath":"epilogue.md","filePath":"epilogue.md"}'),o={name:"epilogue.md"};function t(l,a,h,n,d,s){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="終章" tabindex="-1">終章 <a class="header-anchor" href="#終章" aria-label="Permalink to &quot;終章&quot;">​</a></h1><h2 id="黄金の永遠なる栄光" tabindex="-1">黄金の永遠なる栄光 <a class="header-anchor" href="#黄金の永遠なる栄光" aria-label="Permalink to &quot;黄金の永遠なる栄光&quot;">​</a></h2><p>帝国は興り、そして滅びる。</p><p>王は生まれ、やがて歴史の一部となる。</p><p>都市は姿を変え、人々は世代を重ねてゆく。</p><p>しかし、</p><p>PIGLIN KINGDOM の精神は永遠である。</p><hr><p>王国は黄金のみで築かれたのではない。</p><p>知恵によって。</p><p>勇気によって。</p><p>労働によって。</p><p>忠誠によって。</p><p>そして、人々の団結によって築かれたのである。</p><hr><blockquote><p>王国とは城壁ではない。</p><p>王国とは財宝ではない。</p><p>王国とは、黄金の冠のもとに団結する民そのものである。</p></blockquote><hr><p>初代黄金王</p><h1 id="king-piglin-i" tabindex="-1">KING PIGLIN I <a class="header-anchor" href="#king-piglin-i" aria-label="Permalink to &quot;KING PIGLIN I&quot;">​</a></h1><p>が建国の際に残したこの言葉は、</p><p>幾世代を経てもなお、</p><p>王国の根幹として受け継がれている。</p><hr><h2 id="五つの柱" tabindex="-1">五つの柱 <a class="header-anchor" href="#五つの柱" aria-label="Permalink to &quot;五つの柱&quot;">​</a></h2><p>PIGLIN KINGDOM は、次の五つの柱の上に立つ。</p><h3 id="秩序" tabindex="-1">秩序 <a class="header-anchor" href="#秩序" aria-label="Permalink to &quot;秩序&quot;">​</a></h3><p>法は王国を支える。</p><h3 id="繁栄" tabindex="-1">繁栄 <a class="header-anchor" href="#繁栄" aria-label="Permalink to &quot;繁栄&quot;">​</a></h3><p>富は民を豊かにする。</p><h3 id="忠誠" tabindex="-1">忠誠 <a class="header-anchor" href="#忠誠" aria-label="Permalink to &quot;忠誠&quot;">​</a></h3><p>民は王国を守り、王国は民を守る。</p><h3 id="名誉" tabindex="-1">名誉 <a class="header-anchor" href="#名誉" aria-label="Permalink to &quot;名誉&quot;">​</a></h3><p>高潔なる行いは永遠に語り継がれる。</p><h3 id="知識" tabindex="-1">知識 <a class="header-anchor" href="#知識" aria-label="Permalink to &quot;知識&quot;">​</a></h3><p>知識と技術は未来を切り開く。</p><hr><h2 id="王国の誓い" tabindex="-1">王国の誓い <a class="header-anchor" href="#王国の誓い" aria-label="Permalink to &quot;王国の誓い&quot;">​</a></h2><p>すべての国民は、</p><p>黄金の王冠のもと、</p><p>互いを尊重し、</p><p>王国の繁栄と平和のために力を尽くす。</p><p>王国は国民を守り、</p><p>国民は王国を支える。</p><p>その絆こそが、</p><p>PIGLIN KINGDOM の礎である。</p><hr><h2 id="未来へ" tabindex="-1">未来へ <a class="header-anchor" href="#未来へ" aria-label="Permalink to &quot;未来へ&quot;">​</a></h2><p>時代は変わる。</p><p>新たな技術が生まれ、</p><p>未知の世界が発見され、</p><p>新たな世代が王国を受け継いでいく。</p><p>しかし、</p><p>王国を支える精神は変わることはない。</p><p>黄金の旗は翻り、</p><p>王座は受け継がれ、</p><p>大法典は王国を導き続ける。</p><hr><h2 id="王国万歳" tabindex="-1">王国万歳 <a class="header-anchor" href="#王国万歳" aria-label="Permalink to &quot;王国万歳&quot;">​</a></h2><blockquote><p>黄金は栄光のために。</p><p>栄光は王国のために。</p><p>王国は永遠のために。</p></blockquote><hr><h1 id="国王陛下万歳" tabindex="-1">国王陛下万歳 <a class="header-anchor" href="#国王陛下万歳" aria-label="Permalink to &quot;国王陛下万歳&quot;">​</a></h1><h1 id="piglin-kingdom-万歳" tabindex="-1">PIGLIN KINGDOM 万歳 <a class="header-anchor" href="#piglin-kingdom-万歳" aria-label="Permalink to &quot;PIGLIN KINGDOM 万歳&quot;">​</a></h1><hr><h3 id="long-live-the-king" tabindex="-1">LONG LIVE THE KING <a class="header-anchor" href="#long-live-the-king" aria-label="Permalink to &quot;LONG LIVE THE KING&quot;">​</a></h3><h3 id="long-live-piglin-kingdom" tabindex="-1">LONG LIVE PIGLIN KINGDOM <a class="header-anchor" href="#long-live-piglin-kingdom" aria-label="Permalink to &quot;LONG LIVE PIGLIN KINGDOM&quot;">​</a></h3><hr><p><em>PIGLIN KINGDOM 大法典</em><br><em>第一版</em></p><p><em>王国歴二〇〇年</em><br><em>王立公文書館 編纂</em></p>',68)])])}const I=e(o,[["render",t]]);export{u as __pageData,I as default};
